CREATE FUNCTION public.admin_activity_overview() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; RETURN jsonb_build_object('bells',(SELECT coalesce(jsonb_agg(x),'[]'::jsonb) FROM (SELECT post_id,count(DISTINCT user_id) AS count FROM (SELECT post_id,user_id FROM post_bell_interests UNION SELECT post_id,user_id FROM vehicle_bell_demands UNION SELECT entry_id::uuid,user_id FROM free_work_interests WHERE source='post' AND entry_id ~ '^[0-9a-fA-F-]{36}$') b GROUP BY post_id) x),'chats',(SELECT coalesce(jsonb_agg(x),'[]'::jsonb) FROM (SELECT least(sender_id,receiver_id) AS first_id,greatest(sender_id,receiver_id) AS second_id,count(*) AS count,max(created_at) AS latest FROM messages GROUP BY least(sender_id,receiver_id),greatest(sender_id,receiver_id) ORDER BY latest DESC LIMIT 200) x)); END $$;
REVOKE ALL ON FUNCTION public.admin_activity_overview() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_activity_overview() TO authenticated;
CREATE FUNCTION public.notice_admin_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE actor uuid; label text; BEGIN IF TG_TABLE_NAME='messages' THEN actor:=NEW.sender_id; label:='కొత్త సందేశం నమోదైంది'; ELSE actor:=NEW.user_id; label:=CASE WHEN TG_TABLE_NAME='posts' THEN 'కొత్త ప్రకటన నమోదైంది' ELSE 'ప్రకటనకు గంట నమోదైంది' END; END IF; INSERT INTO public.notifications(user_id,message) SELECT user_id,label FROM public.user_roles WHERE role='admin' AND user_id<>actor AND (TG_TABLE_NAME<>'messages' OR user_id<>NEW.receiver_id); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.notice_admin_activity() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER admin_post_notice AFTER INSERT ON public.posts FOR EACH ROW EXECUTE FUNCTION public.notice_admin_activity();
CREATE TRIGGER admin_message_notice AFTER INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.notice_admin_activity();
CREATE TRIGGER admin_post_bell_notice AFTER INSERT ON public.post_bell_interests FOR EACH ROW EXECUTE FUNCTION public.notice_admin_activity();
CREATE TRIGGER admin_vehicle_bell_notice AFTER INSERT ON public.vehicle_bell_demands FOR EACH ROW EXECUTE FUNCTION public.notice_admin_activity();
CREATE TRIGGER admin_work_bell_notice AFTER INSERT ON public.free_work_interests FOR EACH ROW EXECUTE FUNCTION public.notice_admin_activity();